230	// getSeverityStyle returns style for severity level (Rule 102: the palette
231	// lives in the theme, not here).
232	func (m Model) getSeverityStyle(sev scan.SeverityLevel) lipgloss.Style {
233		return theme.SeverityTextStyle(string(sev))
234	}
