13	// fixState is the state behind the Fix line of a finding detail (DEVDESK-751).
14	type fixState int
15	
16	const (
17		fixManual fixState = iota
18		fixBuiltIn
19		fixBuiltInDeclined
20		fixNoFixPublished
21		fixCannotFixHere
22		fixNoGuidance
23	)
24	
25	// The closed vocabulary of the Fix line (AC1). Only labelBuiltInUnavailable
26	// carries a reason, which Label appends after a colon.
27	const (
28		labelBuiltInAvailable   = "Built-in fix available"
29		labelBuiltInUnavailable = "Built-in fix unavailable"
30		labelManual             = "Manual"
31		labelNoFixPublished     = "No fix published"
32		labelCannotFixHere      = "Cannot fix here"
33		labelNoGuidance         = "No guidance available"
34	)
35	
36	// Reasons a finding's file cannot be opened from the detail (Rule 130).
37	const (
38		reasonFileOutsideTarget = "This file is outside the scanned directory"
39		reasonNoFile            = "This finding names no file"
40	)
41	
42	// fixStatus is the Fix line of a finding detail, in words: a colour or a key
43	// name alone would not say it (Rule 134), so the status never names a key.
44	type fixStatus struct {
45		State   fixState
46		Reason  string // why the built-in fix is unavailable or cannot run here
47		Effect  string // what the fix does: the catalog rule's title, or "Fixed in <v>"
48		Warning string // remediation.Rule.Warning, or ""
49	}
50	
51	// Label is the closed-vocabulary text of the status.
52	func (s fixStatus) Label() string {
53		switch s.State {
54		case fixBuiltIn:
55			return labelBuiltInAvailable
56		case fixBuiltInDeclined:
57			return labelBuiltInUnavailable + ": " + s.Reason
58		case fixManual:
59			return labelManual
60		case fixNoFixPublished:
61			return labelNoFixPublished
62		case fixCannotFixHere:
63			return labelCannotFixHere
64		}
65		return labelNoGuidance
66	}
67	
68	// fixStatusOf says whether f can be fixed and why not. For a misconfiguration
69	// it reads misconfigFixAvailability, the computation behind the shortcut column,
70	// so the detail and the header agree (Rule 130).
71	func fixStatusOf(f scan.Finding, onDisk bool) fixStatus {
72		switch scan.Categorize(f) {
73		case scan.CategoryMisconfiguration:
74			return misconfigFixStatus(f, onDisk)
75		case scan.CategoryVulnerability:
76			if f.FixedIn != "" {
77				return fixStatus{State: fixManual, Effect: "Fixed in " + f.FixedIn}
78			}
79			return fixStatus{State: fixNoFixPublished}
80		}
81		return guidanceStatus(f)
82	}
83	
84	// misconfigFixStatus is the status of a misconfiguration, in the order of
85	// misconfigFixAvailability: an image first, then the catalog, then the guidance
86	// a finding the catalog does not know can still carry.
87	func misconfigFixStatus(f scan.Finding, onDisk bool) fixStatus {
88		rule, a := misconfigFixAvailability(f, onDisk)
89		switch {
90		case !onDisk:
91			return fixStatus{State: fixCannotFixHere, Reason: a.Reason}
92		case a.Enabled():
93			return fixStatus{State: fixBuiltIn, Effect: rule.Title, Warning: rule.Warning}
94		case rule.AVDID != "":
95			return fixStatus{State: fixBuiltInDeclined, Reason: a.Reason}
96		}
97		return guidanceStatus(f)
98	}
99	
100	// guidanceStatus is Manual when the finding tells how to fix it by hand, and
101	// No guidance available when it does not.
102	func guidanceStatus(f scan.Finding) fixStatus {
103		if hasGuidance(f) {
104			return fixStatus{State: fixManual}
105		}
106		return fixStatus{State: fixNoGuidance}
107	}
108	
109	// hasGuidance says whether f carries any instruction: a Resolution, a
110	// FixCommand or a remediation.MissingFor text.
111	func hasGuidance(f scan.Finding) bool {
112		if f.Resolution != "" || f.FixCommand != "" {
113			return true
114		}
115		_, ok := remediation.MissingFor(f)
116		return ok
117	}
118	
119	// runCommand is the text under Run and the text Y copies: the FixCommand trimmed,
120	// when fixAction calls it a command and it holds one line. One computation, two
121	// readers.
122	func runCommand(f scan.Finding) (string, bool) {
123		label, text := fixAction(f)
124		cmd := strings.TrimSpace(text)
125		if label != "Run" || cmd == "" || strings.Contains(cmd, "\n") {
126			return "", false
127		}
128		return cmd, true
129	}
130	
131	// fixSteps are the numbered steps under Do: what a rule the catalog cannot fix
132	// is missing, and a FixCommand that is a sentence rather than a command.
133	func fixSteps(f scan.Finding) []string {
134		var steps []string
135		if _, inCatalog := remediation.FixFor(f); !inCatalog {
136			if text, ok := remediation.MissingFor(f); ok {
137				steps = append(steps, text)
138			}
139		}
140		if label, text := fixAction(f); label == "" && text != "" {
141			steps = append(steps, text)
142		}
143		return steps
144	}
145	
146	// fact is one labelled value of the Where section.
147	type fact struct{ Label, Value string }
148	
149	// whereFacts are the facts under Where, in order: File, Package, Job, Script,
150	// Match. A path is shown the way shortPaths shows it, with its line.
151	func whereFacts(f scan.Finding, target string) []fact {
152		var facts []fact
153		add := func(label, value string) {
154			if value != "" {
155				facts = append(facts, fact{label, value})
156			}
157		}
158		file := shortPaths(f.File, target)
159		if file != "" && f.Line > 0 {
160			file += ":" + strconv.Itoa(f.Line)
161		}
162		add("File", file)
163		add("Package", packageFact(f))
164		add("Job", f.Job)
165		add("Script", f.ScriptLine)
166		add("Match", f.Match)
167		return facts
168	}
169	
170	// packageFact is "name version (kind)", leaving out what is unknown.
171	func packageFact(f scan.Finding) string {
172		if f.PkgName == "" {
173			return ""
174		}
175		out := f.PkgName
176		if f.Version != "" {
177			out += " " + f.Version
178		}
179		if kind := packageKind(f.Class); kind != "" {
180			out += " (" + kind + ")"
181		}
182		return out
183	}
184	
185	// findingFilePath is the absolute path of the finding's file under the scanned
186	// directory, or the reason it cannot be opened. It does no I/O: whether the file
187	// exists is for the viewer to say (Rule 130, "Not knowing"). A path that leaves
188	// the target, by a parent segment or an absolute path elsewhere, is refused.
189	func findingFilePath(f scan.Finding, target string, onDisk bool) (string, shortcut.Availability) {
190		if !onDisk {
191			return "", shortcut.Unavailable(reasonFileNotOnDisk)
192		}
193		if f.File == "" {
194			return "", shortcut.Unavailable(reasonNoFile)
195		}
196		root := filepath.Clean(target)
197		file := filepath.ToSlash(f.File)
198		var path string
199		switch {
200		case file == scanMount || strings.HasPrefix(file, scanMount+"/"):
201			path = filepath.Join(root, filepath.FromSlash(strings.TrimPrefix(file, scanMount)))
202		case filepath.IsAbs(f.File):
203			path = filepath.Clean(f.File)
204		default:
205			path = filepath.Join(root, filepath.FromSlash(file))
206		}
207		rel, err := filepath.Rel(root, path)
208		if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
209			return "", shortcut.Unavailable(reasonFileOutsideTarget)
210		}
211		return path, shortcut.Availability{}
212	}
213	
214	// sameFinding says whether a and b are one finding across a re-scan: the line
215	// is not compared, the fix itself moves it.
216	func sameFinding(a, b scan.Finding) bool {
217		return a.Source == b.Source &&
218			remediation.RuleKey(a.ID) == remediation.RuleKey(b.ID) &&
219			a.File == b.File && a.PkgName == b.PkgName && a.Version == b.Version &&
220			instanceOf(a) == instanceOf(b)
221	}
222	
223	// fixAction says how to show f.FixCommand: ("Run", cmd) for a real command,
224	// ("", instruction) for a sentence such as "Update pkg to 1.2", ("", "") when
225	// there is none.
226	func fixAction(f scan.Finding) (label, text string) {
227		switch {
228		case f.FixCommand == "":
229			return "", ""
230		case scan.IsFixInstruction(f):
231			return "", f.FixCommand
232		}
233		return "Run", f.FixCommand
234	}
