23	// Fixing a misconfiguration in place (§3.78, phase B).
24	//
25	// This is the same act as writing a base image (phase C of §3.2) applied to a
26	// second class of finding, so it is the same key, the same confirmation that
27	// defaults to No, and the same write: the bytes at one located range and
28	// nothing else.
29	//
30	// What differs is that only **some** rules can be fixed. The catalog in
31	// internal/remediation is deliberately finite, and a rule outside it is not a
32	// failure — it is the case the MCP server covers by handing a calling agent the
33	// span and the wording. So ctrl+o greys out here far more often than it does on
34	// the Remediation tab, and that greying is what makes the boundary between the
35	// two paths visible instead of guessed at.
36	
37	// ── Reasons (Rule 130) ───────────────────────────────────────────────────────
38	
39	const (
40		reasonNotMisconfigTab = "Built-in fixes belong to the Misconfigurations tab"
41		reasonFileNotOnDisk   = "This target is an image — its files are inside it, not on disk"
42	)
43	
44	// ── Messages (Rule 109) ──────────────────────────────────────────────────────
45	
46	// MisconfigFixPreparedMsg is the answer to computing the fix: the file as it
47	// would become, and what git says about it. It carries the bytes the
48	// confirmation is about, so the write that follows is that one.
49	type MisconfigFixPreparedMsg struct {
50		Target string
51		File   preparedWrite
52		// Rule is the AVD id, which the verification re-scan is checked against.
53		// Body is what the confirmation shows — the fix's title and the diff — and
54		// the two are separate fields because one is read by a human and the other
55		// compared against a later scan.
56		Rule string
57		Body string
58		// Instance says which occurrence of the rule, for the same reason — see
59		// instanceOf.
60		Instance string
61		// FindingFile is the file the finding points at, which the verification
62		// looks in. It is File.File for every rule but the build context's, whose
63		// fix edits the .dockerignore beside the Dockerfile it reports (§3.81).
64		FindingFile string
65		// Scope is what the verification looks for: the workload an edit clears for
66		// every container, or the zero value for a fix of one occurrence
67		// (DEVDESK-688).
68		Scope remediation.Scope
69		Err   error
70	}
71	
72	// MisconfigFixWrittenMsg reports the write. File is the file written,
73	// FindingFile the one the rule was reported in.
74	type MisconfigFixWrittenMsg struct {
75		Target      string
76		File        string
77		FindingFile string
78		Rule        string
79		Instance    string
80		Scope       remediation.Scope
81		Err         error
82	}
83	
84	// ── Availability ─────────────────────────────────────────────────────────────
85	
86	// canFixMisconfig is the one computation behind the shortcut column and the
87	// handler (Rule 130). It answers in the order the user would ask: am I in the
88	// right place, is there a row, can its file be written at all, and is this rule
89	// one the catalog knows.
90	//
91	// The last question runs the fix itself. That is deliberate: a rule can be in
92	// the catalog and still decline this instance — a base image whose distribution
93	// cannot be identified, a stage that already sets a user — and greying out on
94	// "the catalog has an entry" while the handler then refuses would be exactly
95	// the two computations Rule 130 forbids.
96	func (m Model) canFixMisconfig() shortcut.Availability {
97		if m.activeTab != TabMisconfig {
98			return shortcut.Unavailable(reasonNotMisconfigTab)
99		}
100		f, ok := m.findingsTable.Selected()
101		if !ok {
102			return shortcut.Unavailable(reasonNoFinding)
103		}
104		_, a := misconfigFixAvailability(f, m.result != nil && m.result.TargetType == scan.TargetDirectory)
105		return a
106	}
107	
108	// misconfigFixAvailability is what canFixMisconfig answers for a finding once a
109	// row exists, and what the finding detail reads for its fix status, so the two
110	// cannot disagree (Rule 130). onDisk says whether the target is a directory:
111	// an image's files are inside it, where nothing can be written. It also returns
112	// the catalog rule, whenever the catalog has one, so a caller can say what the
113	// fix would do even where it cannot run.
114	func misconfigFixAvailability(f scan.Finding, onDisk bool) (remediation.Rule, shortcut.Availability) {
115		rule, ok := remediation.FixFor(f)
116		if !onDisk {
117			return rule, shortcut.Unavailable(reasonFileNotOnDisk)
118		}
119		if !ok {
120			return rule, shortcut.Unavailable(noFixReason(f))
121		}
122		// A refusal the finding alone settles (DEVDESK-688): greyed in advance, with
123		// the reason the press of the key would give.
124		if rule.Declines != nil {
125			if reason := rule.Declines(f); reason != "" {
126				return rule, shortcut.Unavailable(reason)
127			}
128		}
129		// Reading the file here would be I/O on a path the header calls every
130		// frame, so the declines that need the content are left to the Cmd and
131		// reach the footer. What is settled here is everything the finding alone
132		// can answer.
133		return rule, shortcut.Availability{}
134	}
135	
136	// noFixReason is why a finding with no fix in the catalog is refused: for a Pod
137	// Security finding, what the manifest is missing (DEVDESK-689); for anything
138	// else, the generic refusal. The fix is tried first, so a rule that has one never
139	// reaches the missing text.
140	func noFixReason(f scan.Finding) string {
141		if text, ok := remediation.MissingFor(f); ok {
142			return text
143		}
144		return remediation.ReasonNoFixForRule
145	}
146	
147	// ── Preparing ────────────────────────────────────────────────────────────────
148	
149	// prepareMisconfigFix starts the fix by computing it: nothing is asked of the
150	// user until the file has been read, rewritten and put to git, so the
151	// confirmation can state what it is about.
152	func (m Model) prepareMisconfigFix() (tea.Model, tea.Cmd) {
153		if a := m.canFixMisconfig(); !a.Enabled() {
154			return m, m.footer.Warn(a.Reason)
155		}
156		f, _ := m.findingsTable.Selected()
157		return m, prepareMisconfigFixCmd(m.targetPath, f)
158	}
159	
160	// prepareMisconfigFixCmd reads the file, asks the catalog for the edits and
161	// applies them. The finding is copied in (Rule 110).
162	//
163	// A rule that declines here is not an error: it is an answer, and it reaches the
164	// footer as a warning rather than as a failure.
165	func prepareMisconfigFixCmd(target string, f scan.Finding) tea.Cmd {
166		return func() tea.Msg {
167			rule, ok := remediation.FixFor(f)
168			if !ok {
169				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{noFixReason(f)}}
170			}
171			rel, reason := rule.FileFor(target, f)
172			if reason != "" {
173				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
174			}
175			path := filepath.Join(target, filepath.FromSlash(rel))
176			original, err := readFile(path)
177			if err != nil {
178				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: err}
179			}
180			edits, reason := rule.Fix(original, f)
181			if reason != "" {
182				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
183			}
184			updated, err := patch.Rewrite(original, edits)
185			if err != nil {
186				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
187			}
188			diff, err := patch.Diff(rel, original, edits)
189			if err != nil {
190				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
191			}
192			file := preparedWrite{File: rel, Path: path, Original: original, Updated: updated}
193			if file.State, err = git.StateOf(path); err != nil {
194				log.Printf("ERROR [security/misconfig] git state of %s: %v", rel, err)
195				file.StateErr = true
196			}
197			body := rule.Title + "\n\n"
198			if rule.Warning != "" {
199				body += "Warning: " + rule.Warning + "\n\n"
200			}
201			return MisconfigFixPreparedMsg{
202				Target: target, File: file, FindingFile: f.File,
203				Rule: f.ID, Instance: instanceOf(f), Body: body + diff,
204				Scope: rule.ScopeOf(updated, edits),
205			}
206		}
207	}
208	
209	// errDeclined carries a catalog refusal through the same channel as a failure,
210	// so the handler has one message to read, and tells the two apart by type rather
211	// than by inspecting a string.
212	type errDeclined struct{ reason string }
213	
214	func (e errDeclined) Error() string { return e.reason }
215	
216	// ── Confirming and writing ───────────────────────────────────────────────────
217	
218	func (m Model) handleMisconfigFixPrepared(msg MisconfigFixPreparedMsg) (tea.Model, tea.Cmd) {
219		if msg.Target != m.targetPath {
220			return m, nil // an answer about a result no longer on screen
221		}
222		if d, ok := msg.Err.(errDeclined); ok {
223			// Nothing failed: the catalog will not fix this instance, and says why.
224			return m, m.footer.Warn(d.reason)
225		}
226		if msg.Err != nil {
227			log.Printf("ERROR [security/misconfig] prepare fix: %v", msg.Err)
228			return m, m.footer.Error("Could not prepare the fix — the file may have changed, check logs")
229		}
230		m.misconfigPending = &msg.File
231		m.misconfigFinding = misconfigFindingRef{Rule: msg.Rule, Instance: msg.Instance, File: msg.FindingFile, Scope: msg.Scope}
232		// Rule 104: the safe answer is the default — ConfirmModal opens on No.
233		m.confirmModal = sharedcomponents.NewConfirmModal("Fix misconfiguration", misconfigConfirmationText(msg.File, msg.Body))
234		return m, nil
235	}
236	
237	// misconfigConfirmationText shows the diff itself, not a summary of it.
238	//
239	// A base image bump is one token replaced by another and reads as a sentence; a
240	// misconfiguration fix inserts a block, and no sentence conveys what is about to
241	// land in the file. What the user agrees to is the diff, so the diff is what the
242	// modal shows — followed by what git will and will not be able to undo.
243	func misconfigConfirmationText(f preparedWrite, body string) string {
244		return body + "\n" + fmt.Sprintf("%s: %s\n", f.File, gitAdvice(f))
245	}
246	
247	// handleMisconfigFixConfirmed runs the write the modal was about.
248	func (m Model) handleMisconfigFixConfirmed() (tea.Model, tea.Cmd) {
249		file, ref := m.misconfigPending, m.misconfigFinding
250		m.misconfigPending = nil
251		m.misconfigFinding = misconfigFindingRef{}
252		m.confirmModal = nil
253		if file == nil {
254			return m, nil
255		}
256		return m, writeMisconfigFixCmd(m.targetPath, ref, *file)
257	}
258	
259	func writeMisconfigFixCmd(target string, ref misconfigFindingRef, f preparedWrite) tea.Cmd {
260		return func() tea.Msg {
261			err := patch.WriteIfUnchanged(f.Path, f.Original, f.Updated)
262			return MisconfigFixWrittenMsg{
263				Target: target, File: f.File, FindingFile: ref.File,
264				Rule: ref.Rule, Instance: ref.Instance, Scope: ref.Scope, Err: err,
265			}
266		}
267	}
268	
269	// misconfigFindingRef is the finding a pending fix is about, kept between the
270	// confirmation and the write so the verification knows what to look for.
271	type misconfigFindingRef struct {
272		// Rule is the AVD id.
273		Rule string
274		// Instance is which occurrence of it, so a file holding the same rule
275		// twice is not judged by the one the fix did not touch.
276		Instance string
277		// File is where the finding points, which is not always the file written.
278		File string
279		// Scope is the workload the fix clears, when it clears one.
280		Scope remediation.Scope
281	}
282	
283	func (m Model) handleMisconfigFixWritten(msg MisconfigFixWrittenMsg) (tea.Model, tea.Cmd) {
284		if msg.Target != m.targetPath {
285			return m, nil
286		}
287		if msg.Err != nil {
288			cmd := m.reportFailedFix(msg)
289			return m, cmd
290		}
291		// The file changed; the result did not. A re-scan is what turns "written"
292		// into "fixed", so it starts here rather than being left to the user — as a
293		// job, visible in `:jobs` and stoppable with K.
294		v := misconfigVerify{Target: msg.Target, Rule: msg.Rule, File: msg.FindingFile, Instance: msg.Instance, Scope: msg.Scope}
295		m.misconfigVerifying = &v
296		scan := m.startMisconfigVerification(v)
297		footer := m.footer.Info(fmt.Sprintf("Fixed %s — re-scanning to confirm %s is gone", msg.File, msg.Rule))
298		return m, tea.Batch(scan, footer)
299	}
300	
301	// reportFailedFix sets the footer on the model it is called on, which is why it
302	// takes a pointer: on a copy the message would be set and then thrown away.
303	func (m *Model) reportFailedFix(msg MisconfigFixWrittenMsg) tea.Cmd {
304		if errors.Is(msg.Err, patch.ErrChanged) {
305			return m.footer.Error(fmt.Sprintf("%s changed since the preview — review it again", msg.File))
306		}
307		log.Printf("ERROR [security/misconfig] write %s: %v", msg.File, msg.Err)
308		return m.footer.Error(fmt.Sprintf("Failed to write %s — check logs", msg.File))
309	}
310	
311	// ── Verifying (§3.78, phase B3) ──────────────────────────────────────────────
312	//
313	// A written file is not a fixed one. The rule that was faulted is still in the
314	// result on screen, because that result was measured before the edit — and the
315	// whole discipline §3.2 set for base images is that a fix is judged by a
316	// re-scan, never by the confidence of whatever produced it. So the write starts
317	// one, and the verdict it reports is binary: the rule is gone, or it is not.
318	//
319	// The scan is an ordinary job (§3.58), which is what makes starting it on the
320	// user's behalf acceptable: it shows up in `:jobs` with a label saying why, and
321	// `K` stops it. Nothing is hidden and nothing is unstoppable.
322	
323	// misconfigVerify is the fix waiting on a re-scan to say whether it worked.
324	type misconfigVerify struct {
325		Target string
326		Rule   string
327		// File is the file the finding points at, where the rule is looked for.
328		File     string
329		Instance string
330		// Scope is what a rule that clears a whole workload is looked for in
331		// (DEVDESK-688). The zero value: this occurrence, through holdsRule.
332		Scope remediation.Scope
333	}
334	
335	// MisconfigVerifiedMsg is the verdict: whether the rule the fix was about is
336	// still reported for that file.
337	type MisconfigVerifiedMsg struct {
338		Target  string
339		Rule    string
340		File    string
341		Cleared bool
342		// Scope is the scope the verdict was judged by; the zero value for a fix of
343		// one occurrence.
344		Scope remediation.Scope
345		// Still lists the rule ids the re-scan still reports in the scope of the
346		// fix; Cleared is true when it is empty (DEVDESK-688).
347		Still []string
348		// Result is the scan the verdict was read from, so the tab can stop showing
349		// findings the edit has already dealt with.
350		Result *scan.Result
351		Err    error
352	}
353	
354	// startMisconfigVerification re-scans the target the fix was written into.
355	//
356	// It runs even when the catalog is sure of itself, because being sure is not
357	// the same as having measured — and the cases where a rule survives its own fix
358	// are exactly the ones nobody predicted.
359	func (m Model) startMisconfigVerification(v misconfigVerify) tea.Cmd {
360		if m.scanningTarget(v.Target) {
361			// Something is already measuring this target; its result will answer.
362			return nil
363		}
364		job := inventoryScanJob{Kind: kindRepo, Name: v.Target}
365		opts := m.scanOptions()
366		return jobs.StartInContext(
367			jobs.NewRun(jobs.KindScan, command.ViewSecurity, "", "verify fix", v.Target),
368			func(contextName string) tea.Cmd {
369				return rescanCmd([]inventoryScanJob{job}, opts, contextName)
370			},
371		)
372	}
373	
374	// verifyMisconfigCmd reads the result the re-scan stored and answers whether the
375	// rule is still there. It runs off Update (Rule 110).
376	func verifyMisconfigCmd(v misconfigVerify) tea.Cmd {
377		return func() tea.Msg {
378			result, err := cache.ReadWorkspaceScanResult(v.Target)
379			if err != nil {
380				return MisconfigVerifiedMsg{Target: v.Target, Rule: v.Rule, File: v.File, Err: err}
381			}
382			still := stillReported(result, v)
383			return MisconfigVerifiedMsg{
384				Target: v.Target, Rule: v.Rule, File: v.File,
385				Cleared: len(still) == 0, Still: still, Scope: v.Scope, Result: result,
386			}
387		}
388	}
389	
390	// stillReported lists the rule ids the result still reports for the fix v.
391	//
392	// Without a scope it is holdsRule on the occurrence that was fixed. With one, it
393	// is each rule of the scope looked for in the lines of the edited workload: one
394	// edit cleared them for every container of the pod, so a finding on another
395	// container still counts, and a finding of another workload of the file does not.
396	// A scope with no lines (0, 0: the computation failed) reads the whole file, the
397	// safe side: "still reported" at worst, never a "fixed" that was not measured.
398	func stillReported(result *scan.Result, v misconfigVerify) []string {
399		if len(v.Scope.Rules) == 0 {
400			if holdsRule(result, v.Rule, v.File, v.Instance) {
401				return []string{v.Rule}
402			}
403			return nil
404		}
405		if result == nil {
406			return nil
407		}
408		var still []string
409		for _, rule := range v.Scope.Rules {
410			if holdsRuleInScope(result, rule, v.File, v.Scope) {
411				still = append(still, rule)
412			}
413		}
414		return still
415	}
416	
417	// holdsRuleInScope says whether the result reports rule in file, at a line that
418	// is inside the scope's lines (anywhere in the file when the scope has none). A
419	// finding with no line (Line <= 0) cannot be placed outside the scope, so it
420	// counts as inside: the safe side.
421	func holdsRuleInScope(result *scan.Result, rule, file string, scope remediation.Scope) bool {
422		want := remediation.RuleKey(rule)
423		wholeFile := scope.Line == 0 && scope.EndLine == 0
424		for _, f := range result.Findings {
425			if scan.Categorize(f) != scan.CategoryMisconfiguration || f.File != file || remediation.RuleKey(f.ID) != want {
426				continue
427			}
428			if wholeFile || f.Line <= 0 || (f.Line >= scope.Line && f.Line <= scope.EndLine) {
429				return true
430			}
431		}
432		return false
433	}
434	
435	// holdsRule says whether a result still reports this rule for this file —
436	// and, when instance is set, this occurrence of it.
437	//
438	// It matches through remediation.RuleKey rather than on the string, for the
439	// reason the catalog does: Trivy spells one rule two ways, and a comparison
440	// that missed the other spelling would report every fix as successful.
441	//
442	// The occurrence matters for a manifest (§3.80): a Deployment with two
443	// containers is flagged for KSV-0001 twice in one file, and the fix edits one
444	// of them. Judged on the rule and the file alone, the untouched container
445	// would read as the fix having failed.
446	func holdsRule(result *scan.Result, rule, file, instance string) bool {
447		if result == nil {
448			return false
449		}
450		want := remediation.RuleKey(rule)
451		for _, f := range result.Findings {
452			if scan.Categorize(f) != scan.CategoryMisconfiguration {
453				continue
454			}
455			if f.File == file && remediation.RuleKey(f.ID) == want && (instance == "" || instanceOf(f) == instance) {
456				return true
457			}
458		}
459		return false
460	}
461	
462	// instanceOf identifies one occurrence of a rule in a file, without its line,
463	// which the fix itself moves. Trivy words the occurrence in Message ("Container
464	// 'api' of Deployment 'web' should set…"), kubeconform in Title
465	// ("Deployment/web: …"); the pair covers both.
466	func instanceOf(f scan.Finding) string {
467		return f.Title + "\n" + f.Message
468	}
469	
470	// handleMisconfigVerified reports the verdict, and swaps in the result it was
471	// read from.
472	//
473	// The swap is what keeps the screen from contradicting the footer: without it a
474	// line saying the rule is gone would sit above a table still listing it.
475	func (m Model) handleMisconfigVerified(msg MisconfigVerifiedMsg) (tea.Model, tea.Cmd) {
476		if msg.Target != m.targetPath {
477			return m, nil
478		}
479		m.misconfigVerifying = nil
480		if msg.Err != nil {
481			log.Printf("ERROR [security/misconfig] verify %s: %v", msg.Rule, msg.Err)
482			return m, m.footer.Error("Could not read the verification scan — check logs")
483		}
484		if msg.Result != nil {
485			m.setResult(msg.Result)
486		}
487		if !msg.Cleared {
488			// Not a failure: the file was written, and the rule still fires. Saying
489			// so is the only honest answer, and it is why the scan exists.
490			ids := msg.Still
491			if len(ids) == 0 {
492				ids = []string{msg.Rule}
493			}
494			return m, m.footer.Warn(fmt.Sprintf("%s still reported in %s after the fix", strings.Join(ids, " and "), msg.File))
495		}
496		if len(msg.Scope.Rules) > 0 {
497			return m, m.footer.Info(fmt.Sprintf("%s cleared for the whole pod in %s — confirmed by a re-scan",
498				strings.Join(msg.Scope.Rules, " and "), msg.File))
499		}
500		return m, m.footer.Info(fmt.Sprintf("%s cleared in %s — confirmed by a re-scan", msg.Rule, msg.File))
501	}
