17	// handleDetailsState processes input in details state
18	func (m Model) handleDetailsState(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
19		switch msg.String() {
20		// backspace was an alias of esc, and the only one in the application.
21		case "esc":
22			m.state = StateResults
23			return m, nil
24		case keymap.Web:
25			return m.handleDetailsOpenReference()
26		case "up":
27			m.detailsViewport.ScrollUp(1)
28		case "down":
29			m.detailsViewport.ScrollDown(1)
30		case "pgup":
31			m.detailsViewport.HalfPageUp()
32		case "pgdown":
33			m.detailsViewport.HalfPageDown()
34		case "home":
35			m.detailsViewport.GotoTop()
36		case "end":
37			m.detailsViewport.GotoBottom()
38		}
39		return m, nil
40	}
41	
42	// handleDetailsOpenReference opens the first reference URL in the default browser.
43	func (m Model) handleDetailsOpenReference() (tea.Model, tea.Cmd) {
44		if m.selectedFinding == nil {
45			return m, nil
46		}
47		f := *m.selectedFinding
48		if len(f.References) == 0 {
49			return m, m.footer.Warn("No references available")
50		}
51		url := f.References[0]
52		return m, func() tea.Msg {
53			if err := browser.Open(url); err != nil {
54				log.Printf("ERROR [security] open URL %s: %v", url, err)
55			}
56			return nil
57		}
58	}
59	
60	// sizeDetails gives the details viewport the room the router leaves it: the
61	// view's width less the two border cells the viewport frame takes, so a line
62	// never reaches under the right border. The padding takes one more cell on each
63	// side, which is the text width (detailsTextWidth).
64	func (m *Model) sizeDetails() {
65		m.detailsViewport.SetWidth(max(m.width-2, 1))
66		m.detailsViewport.SetHeight(m.height)
67	}
68	
69	// detailsTextWidth is how many cells a line of the detail text may span: one
70	// column, never wider than maxColumnWidth.
71	func (m Model) detailsTextWidth() int { return min(max(m.width-4, 1), maxColumnWidth) }
72	
73	// scanTarget is the scanned path, for display only: it is what shortPaths cuts
74	// off a path, and an image reference there is ignored.
75	func (m Model) scanTarget() string {
76		if m.result == nil {
77			return ""
78		}
79		return m.result.Target
80	}
81	
82	// targetOnDisk says whether the scanned target is a directory, whose files a
83	// built-in fix can write.
84	func (m Model) targetOnDisk() bool {
85		return m.result != nil && m.result.TargetType == scan.TargetDirectory
86	}
87	
88	// buildDetailsContent builds the full scrollable content for the details view.
89	//
90	// What to do comes before why: the Fix block (status, Where, Do, Run, Effect),
91	// then Why, the scanner's Output and the Refs. Each section is emitted only when
92	// it has something to say, and sections are joined by exactly one blank line.
93	func (m Model) buildDetailsContent() string {
94		if m.selectedFinding == nil {
95			return theme.Bg("No finding selected")
96		}
97	
98		f := *m.selectedFinding
99		t := newDetailsText(m.detailsTextWidth())
100	
101		var sections []string
102		for _, section := range [][]string{
103			m.detailsHeader(f, t),
104			m.detailsFix(f, t),
105			m.detailsWhy(f, t),
106			m.detailsOutput(f, t),
107			m.detailsReferences(f, t),
108		} {
109			if len(section) > 0 {
110				sections = append(sections, strings.Join(section, "\n"))
111			}
112		}
113	
114		return lipgloss.NewStyle().
115			Padding(1).
116			Background(theme.ColorBackground).
117			Render(strings.Join(sections, "\n\n"))
118	}
119	
120	// detailsHeader is the severity and ID, then the title on one line: a title can
121	// carry a whole stderr line, and the Message below has the rest.
122	func (m Model) detailsHeader(f scan.Finding, t detailsText) []string {
123		sev := string(f.Severity)
124		header := m.getSeverityStyle(f.Severity).Render(sev) + theme.Bg(" ") +
125			theme.TitleStyle.Render(oneLine(f.ID, t.width-ansi.StringWidth(sev)-1))
126		title := oneLine(shortPaths(f.Title, m.scanTarget()), t.width)
127		return []string{header, t.text.Render(title)}
128	}
129	
130	// detailsFix is the Fix block: the status in words, then, with no blank line
131	// between them, where the finding is, what to do, the command to run and what the
132	// fix does. It is written in ColorText alone (DEVDESK-751, AC7): ColorDim, the
133	// sub-title and the warning colours fall under 4.5:1 on several shipped themes,
134	// so the word "Warning:" carries the warning.
135	func (m Model) detailsFix(f scan.Finding, t detailsText) []string {
136		status := fixStatusOf(f, m.targetOnDisk())
137		lines := t.field("Fix: ", status.Label(), t.text)
138		lines = append(lines, m.detailsWhere(f, t)...)
139		lines = append(lines, t.list("Do: ", fixSteps(f), f.Resolution, t.text)...)
140		lines = append(lines, detailsRun(f, t)...)
141		lines = append(lines, t.field("Effect: ", status.Effect, t.text)...)
142		return append(lines, t.field("Warning: ", status.Warning, t.text)...)
143	}
144	
145	// detailsWhere is the file, then the other facts that place the finding, each on
146	// its own line under the first.
147	func (m Model) detailsWhere(f scan.Finding, t detailsText) []string {
148		const label = "Where: "
149		facts := whereFacts(f, m.scanTarget())
150		if len(facts) == 0 {
151			return nil
152		}
153		first := facts[0].Value
154		if facts[0].Label != "File" {
155			first = facts[0].Label + ": " + first
156		}
157		lines := t.field(label, first, t.text)
158		for _, fc := range facts[1:] {
159			lines = append(lines, t.fieldAt(ansi.StringWidth(label), fc.Label+": ", fc.Value, t.text)...)
160		}
161		return lines
162	}
163	
164	// detailsRun is the command on one line, cut when it is wider than the column:
165	// the copy key puts the whole of it on the clipboard.
166	func detailsRun(f scan.Finding, t detailsText) []string {
167		const label = "Run: "
168		cmd, ok := runCommand(f)
169		if !ok {
170			return nil
171		}
172		return []string{t.heading(label) + t.text.Render(oneLine("$ "+cmd, t.width-ansi.StringWidth(label)))}
173	}
174	
175	// detailsWhy is the reason the finding matters: the scanner's description, the
176	// Pod Security profile, where the finding comes from and its type.
177	func (m Model) detailsWhy(f scan.Finding, t detailsText) []string {
178		var lines []string
179		if strings.TrimSpace(f.Description) != "" {
180			lines = t.block(f.Description, t.text)
181		}
182		lines = append(lines, t.field("Pod Security: ", pssLabel(f), t.text)...)
183		lines = append(lines, t.field("Source: ", f.Source, t.text)...)
184		lines = append(lines, t.field("Type: ", f.IaCType, t.text)...)
185		if len(lines) == 0 {
186			return nil
187		}
188		return append([]string{t.heading("Why:")}, lines...)
189	}
190	
191	// detailsOutput is what the scanner said about this instance, capped: the start
192	// of it is what tells two findings of one rule apart, and the rest is in the log.
193	// A message that only repeats the title or the description adds nothing.
194	func (m Model) detailsOutput(f scan.Finding, t detailsText) []string {
195		msg := strings.TrimSpace(f.Message)
196		if msg == "" || msg == strings.TrimSpace(f.Title) || msg == strings.TrimSpace(f.Description) {
197			return nil
198		}
199		lines, hidden := cappedLines(dropBlankLines(shortPaths(msg, m.scanTarget())), t.width, maxMessageLines)
200		if len(lines) == 0 {
201			return nil
202		}
203		out := []string{t.heading("Output:")}
204		for _, line := range lines {
205			out = append(out, t.text.Render(line))
206		}
207		if more := moreLines(hidden); more != "" {
208			out = append(out, theme.DimStyle.Render(more))
209		}
210		return out
211	}
212	
213	// detailsReferences are the reference URLs, one per line.
214	func (m Model) detailsReferences(f scan.Finding, t detailsText) []string {
215		if len(f.References) == 0 {
216			return nil
217		}
218		lines := []string{t.heading("Refs:")}
219		for _, ref := range f.References {
220			lines = append(lines, t.indented("  ", ref, t.text)...)
221		}
222		return lines
223	}
224	
225	// renderDetailsView renders the scrollable details viewport.
226	func (m Model) renderDetailsView() string {
227		return m.detailsViewport.View()
228	}
229	
230	// getSeverityStyle returns style for severity level (Rule 102: the palette
231	// lives in the theme, not here).
232	func (m Model) getSeverityStyle(sev scan.SeverityLevel) lipgloss.Style {
233		return theme.SeverityTextStyle(string(sev))
234	}
235	
236	// HeaderView interface implementation
237	
238	// packageKind says what has to move to clear a vulnerability, from the class
239	// Trivy reported. Empty for a result cached before the class was recorded: it
240	// is unknown, and is not shown rather than guessed.
241	func packageKind(class string) string {
242		switch class {
243		case scan.ClassOSPackages:
244			return "Base image package"
245		case scan.ClassLangPackages:
246			return "Application dependency"
247		}
248		return ""
249	}
