23	// The scan itself runs Trivy and Gitleaks in containers, and the browser and
24	// cache commands reach the desktop and the disk. No test executes one: results,
25	// progress updates and dependency checks are fed in as messages, and the
26	// assertions are on model state.
27	//
28	// These tests drive Update() and View() only — model.go is 1977 lines, the
29	// largest file in the project and due to be split, so assertions on its
30	// internals would pin the current layout.
31	//
32	// The form persists every toggle with config.Save, so HOME is redirected for
33	// the whole package: a test must not rewrite the developer's ~/.devdesk.
34	
35	func TestMain(m *testing.M) {
36		log.SetOutput(io.Discard)
37		// No engine and no registry is reached from a test (§3.88).
38		localImageDigests = func([]string) map[string][]string { return nil }
39		checkImageUpdates = func([]string) map[string]imageupdate.Facts { return nil }
40		// Nor cosign, through the Remediation tab's signature checks (§3.82).
