154	// renderInfoLine is the footer's message line, always rendered even when empty
155	// (Rule 124). The message expires on its own after three seconds (Rule 128).
156	func (m Model) renderInfoLine(width int) string {
157		return m.footer.View(width, m.status())
158	}
159	
160	// status is what the footer says when no message is in flight.
161	//
162	// A stage that failed is a **state** of the result rather than an event: it is
163	// true for as long as the result is on screen, and a message would expire after
164	// three seconds — the distinction Rule 128 draws between the two. It carries
165	// the error level, because that is what happened, and it names the stages so
166	// the log can be searched for them.
167	func (m Model) status() sharedcomponents.Status {
168		if m.state == StateInventory {
169			return m.inventoryStatus()
170		}
171		// Which lines of a long detail are on screen: a state of the screen, derived
172		// here and never stored, so no timer can take it away (Rule 128).
173		if m.state == StateDetails {
174			vp := m.detailsViewport
175			return sharedcomponents.Status{Text: scrollPosition(vp.YOffset(), vp.VisibleLineCount(), vp.TotalLineCount())}
176		}
177		// Ahead of the failed stages below: on this tab what is happening now is
178		// what the footer is for, and a stage that failed still shows on the others.
179		if status, ok := m.remediationStatus(); ok {
180			return status
181		}
182		if m.state != StateResults || m.result == nil || len(m.result.Errors) == 0 {
183			return sharedcomponents.Status{}
184		}
185		return sharedcomponents.Status{
186			Text:  failedStages(m.result.Errors) + " — check logs",
187			Level: sharedcomponents.LevelError,
188		}
189	}
190	
191	// inventoryStatus is the inventory footer: the selected row's own activity
192	// (its detail), composed with the batch progress or, while the caches are
193	// read, the load text. The load no longer hides the row: a failed row still
194	// says so under a ctrl+r.
195	func (m Model) inventoryStatus() sharedcomponents.Status {
196		st := sharedcomponents.Status{Text: sharedcomponents.JobsStatusLine(m.jobs, command.ViewSecurity)}
197		if m.inventoryLoading {
198			st.Text = "Loading scan inventory..."
199		}
200		moving := false
201		if row, ok := m.inventory.Selected(); ok {
202			a := m.rowActivity(row)
203			st.Detail = a.Detail
204			moving = a.State == indicator.Running || a.State == indicator.Queued
205		}
206		// The load and jobs work share the one activity dot; only a detail whose dot
207		// moves replaces it (a failed row's is fixed).
208		st.Activity = m.inventoryLoading ||
209			len(jobs.Unfinished(m.jobs)) > 0 && (!moving || st.Detail.IsZero())
210		return st
211	}
