213	// failedStages names what failed, reading the "<stage>: <reason>" that
214	// scan.recordStageError writes. The reason stays in the log: a footer is one
215	// line, and a tool's stderr is not.
216	func failedStages(errs []string) string {
217		stages := make([]string, 0, len(errs))
218		for _, e := range errs {
219			stage := e
220			if idx := strings.Index(e, ": "); idx != -1 {
221				stage = e[:idx]
222			}
223			stages = append(stages, stage)
224		}
225		return strings.Join(stages, ", ") + " failed"
226	}
