// keySwitchClauses returns every key-switch clause from the views.
//
// A switch is recognized as being about keys when one of its clauses
// cites a structural key or a ctrl+/alt+ combination. This is safer than
// relying on the name of the tested expression: msg.String() is not the
// only form, and a switch on runtime.GOOS or on a severity contains none
// of these strings.
func keySwitchClauses(t *testing.T) []caseClause {
	t.Helper()

	seen := map[string]bool{}
	var clauses []caseClause
	consts := keymapConstants(t)

	for _, root := range scannedTrees {
		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
				return nil
			}
			// This package declares the vocabulary; it necessarily cites it.
			if strings.Contains(filepath.ToSlash(path), "internal/ui/keymap/") {
				return nil
			}
			if seen[path] {
				return nil
			}
			seen[path] = true

			fset := token.NewFileSet()
			file, err := parser.ParseFile(fset, path, nil, 0)
			if err != nil {
				t.Fatalf("parse %s: %v", path, err)
			}

			ast.Inspect(file, func(n ast.Node) bool {
				sw, ok := n.(*ast.SwitchStmt)
				if !ok || sw.Body == nil {
					return true
				}
				parsed := clausesOf(sw, fset, path, consts)
				if !isKeySwitch(parsed) {
					return true
				}
				if isModalSwitch(parsed) {
					for i := range parsed {
						parsed[i].isModal = true
					}
				}
				clauses = append(clauses, parsed...)
				return true
			})
			return nil
		})
		if err != nil {
			t.Fatalf("walk %s: %v", root, err)
		}
	}

	if len(clauses) == 0 {
		t.Fatal("no key switch found — the scan is broken, not the code")
	}
	return clauses
}

// keymapConstants returns every top-level string constant declared in keymap.go,
// name to value (New is "N", CommandMode is "ctrl+p", Space is " "). It is parsed
// rather than listed by hand so a new constant is read without touching the test.
func keymapConstants(t *testing.T) map[string]string {
	t.Helper()
	file, err := parser.ParseFile(token.NewFileSet(), "keymap.go", nil, 0)
	if err != nil {
		t.Fatalf("parse keymap.go: %v", err)
	}
	out := map[string]string{}
	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.CONST {
			continue
		}
		for _, spec := range gen.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			for i, name := range vs.Names {
				if i >= len(vs.Values) {
					continue
				}
				lit, ok := vs.Values[i].(*ast.BasicLit)
				if !ok || lit.Kind != token.STRING {
					continue
				}
				if v, err := strconv.Unquote(lit.Value); err == nil {
					out[name.Name] = v
				}
			}
		}
	}
	return out
}

// clausesOf reads the string literals of a switch's clauses, and the keymap.X
// selectors through consts: once " " is written keymap.Space, a switch whose only
// structural key is the space must still be recognized as a key switch.
func clausesOf(sw *ast.SwitchStmt, fset *token.FileSet, path string, consts map[string]string) []caseClause {
	var out []caseClause
	for _, stmt := range sw.Body.List {
		cc, ok := stmt.(*ast.CaseClause)
		if !ok || len(cc.List) == 0 {
			continue
		}
		var keys []string
		for _, expr := range cc.List {
			if sel, ok := expr.(*ast.SelectorExpr); ok {
				if pkg, ok := sel.X.(*ast.Ident); ok && pkg.Name == "keymap" {
					if value, ok := consts[sel.Sel.Name]; ok {
						keys = append(keys, value)
					}
				}
				continue
			}
			lit, ok := expr.(*ast.BasicLit)
			if !ok || lit.Kind != token.STRING {
				continue
			}
			value, err := strconv.Unquote(lit.Value)
			if err != nil {
				continue
			}
			keys = append(keys, value)
		}
		if len(keys) == 0 {
			continue
		}
		position := fset.Position(cc.Pos())
		out = append(out, caseClause{
			where: filepath.ToSlash(path) + ":" + strconv.Itoa(position.Line),
			keys:  keys,
		})
	}
	return out
}

func isKeySwitch(clauses []caseClause) bool {
	for _, clause := range clauses {
		for _, key := range clause.keys {
			if structuralKeys[key] ||
				strings.HasPrefix(key, "ctrl+") ||
				strings.HasPrefix(key, "alt+") ||
				strings.HasPrefix(key, "shift+") {
				return true
			}
		}
	}
	return false
}

// isModalSwitch recognizes a confirmation modal's switch by the fact that
// it binds y and n in lowercase — which no view does.
func isModalSwitch(clauses []caseClause) bool {
	var yes, no bool
	for _, clause := range clauses {
		for _, key := range clause.keys {
			switch key {
			case "y":
				yes = true
			case "n":
				no = true
			}
		}
	}
	return yes && no
}

func exceptionKeys() []string {
	out := make([]string, 0, len(exceptions))
	for _, e := range exceptions {
		out = append(out, e.Key+" ("+e.Surface+")")
	}
	return out
}

