		"no shortcuts":   {},
		"few shortcuts":  {shortcuts: manyShortcuts(3)},
		"many shortcuts": {shortcuts: manyShortcuts(12)},
	}
	for name, v := range views {
		for _, sz := range hintSizes {
			a := routerAt(t, v, sz.w, sz.h)
