			for i, line := range header {
				if got := lipgloss.Width(line); got != sz.w {
					t.Errorf("%s %dx%d: row %d is %d cells wide, want %d", name, sz.w, sz.h, i, got, sz.w)
				}
			}
		}
	}
}

