					switch msg.(type) {
					case uiviewer.OpenRequestMsg, FixCommandCopiedMsg:
						t.Errorf("a refused key emitted %T", msg)
					}
				}
			})
		}
	}
	if len(*written) != 0 {
		t.Errorf("a refused key wrote %q to the clipboard", *written)
	}
