		t.Error("the pending write outlived a No")
	}
	if m.state != StateDetails || m.selectedFinding == nil {
		t.Error("No left the detail")
	}
	if got := fixFile(t, dir); got != fixableDockerfile {
		t.Errorf("No wrote the file:\n%s", got)
	}
}

